package dustin.cex.domains.kyc;
import dustin.cex.domains.account.*;
import dustin.cex.domains.auth.model.entity.*;
import dustin.cex.domains.auth.model.dto.SigninRequest;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

/** 실제 세션·JWT 필터·DB 잠금·감사로 본인 조회/회수와 갱신 경쟁을 검증한다. */
class CustomerSessionControlIntegrationTest extends EddTestSupport {
    @Autowired CustomerSessionControl control;
    RefreshToken extra(){return tokens.saveAndFlush(RefreshToken.builder().userId(customer.getId()).tokenHash(sha(UUID.randomUUID().toString())).expiresAt(LocalDateTime.now().plusHours(1)).build());}
    @Test void listContainsOnlyOwnMetadataAndMarksCurrent(){var other=extra();var page=control.own(customer.getId(),sid,null);assertEquals(2,page.items().size());assertEquals(1,page.items().stream().filter(CustomerSessionControl.Session::current).count());String raw=json.writeValueAsString(page);for(String secret:List.of(other.getTokenHash(),"tokenHash","mfaCredential","userId",customer.getEmail()))assertFalse(raw.contains(secret));}
    @Test void revokedAndExpiredAreDistinguished(){var revoked=extra();revoked.setRevoked(true);tokens.saveAndFlush(revoked);var expired=extra();expired.setExpiresAt(LocalDateTime.now().minusSeconds(1));tokens.saveAndFlush(expired);var items=control.own(customer.getId(),sid,null).items();assertEquals(CustomerSessionControl.State.REVOKED,items.stream().filter(x->x.id().equals(revoked.getSessionId())).findFirst().orElseThrow().state());assertEquals(CustomerSessionControl.State.EXPIRED,items.stream().filter(x->x.id().equals(expired.getSessionId())).findFirst().orElseThrow().state());}
    @Test void pagesPreserveAllSameTimestampRows(){for(int i=0;i<28;i++)extra();jdbc.update("UPDATE refresh_tokens SET created_at=? WHERE user_id=?",java.sql.Timestamp.valueOf(LocalDateTime.now().minusSeconds(1)),customer.getId());var first=control.own(customer.getId(),sid,null);var next=control.own(customer.getId(),sid,first.next());var ids=new HashSet<UUID>();first.items().forEach(x->assertTrue(ids.add(x.id())));next.items().forEach(x->assertTrue(ids.add(x.id())));assertEquals(29,ids.size());assertNull(next.next());}
    @Test void foreignAndAbsentTargetAreEquallyNotFound(){for(UUID target:List.of(maker.sid(),UUID.randomUUID()))assertEquals(404,assertThrows(ResponseStatusException.class,()->control.revoke(customer.getId(),sid,target)).getStatusCode().value());}
    @Test void otherSessionRevocationCanBeReplayed(){var target=extra();assertFalse(control.revoke(customer.getId(),sid,target.getSessionId()).requiresLogin());assertEquals(control.revoke(customer.getId(),sid,target.getSessionId()),control.revoke(customer.getId(),sid,target.getSessionId()));assertTrue(tokens.findBySessionId(target.getSessionId()).orElseThrow().getRevoked());}
    @Test void currentRevocationImmediatelyBlocksOldAccessJwt() throws Exception {assertTrue(control.revoke(customer.getId(),sid,sid).requiresLogin());mvc.perform(get("/api/auth/me").header("Authorization","Bearer "+customerAccess)).andExpect(status().isUnauthorized());assertThrows(ResponseStatusException.class,()->control.own(customer.getId(),sid,null));}
    @Test void revokedRefreshTokenCannotRotate(){var login=auth.signin(new SigninRequest(customer.getEmail(),"security-test-password"));UUID current=UUID.fromString(jwt.verifyAccessToken(login.getAccessToken()).get("sid",String.class));control.revoke(customer.getId(),current,current);assertThrows(dustin.cex.domains.auth.exception.AuthException.class,()->auth.refreshAccessToken(login.getRefreshToken()));}
    @Test void revocationAuditFailureRollsBackFlag(){var target=extra();doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_SESSION_REVOKED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->control.revoke(customer.getId(),sid,target.getSessionId()));reset(audit);assertFalse(tokens.findBySessionId(target.getSessionId()).orElseThrow().getRevoked());}
    @Test void listAuditFailurePreventsResponse(){doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_SESSIONS_LISTED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->control.own(customer.getId(),sid,null));}
    @Test void operatorForeignAndDisabledSessionsCannotUseCustomerFlow(){assertThrows(ResponseStatusException.class,()->control.own(maker.user().getId(),maker.sid(),null));assertThrows(ResponseStatusException.class,()->control.own(customer.getId(),maker.sid(),null));var u=users.findById(customer.getId()).orElseThrow();u.setEnabled(false);users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->control.own(customer.getId(),sid,null));}
    @Test void invalidCursorAndAmbientMutationAreRejected(){for(var c:List.of(new CustomerSessionControl.Cursor(null,UUID.randomUUID()),new CustomerSessionControl.Cursor(LocalDateTime.now().plusDays(1),UUID.randomUUID())))assertThrows(ResponseStatusException.class,()->control.own(customer.getId(),sid,c));assertThrows(org.springframework.transaction.IllegalTransactionStateException.class,()->new org.springframework.transaction.support.TransactionTemplate(manager).execute(t->control.revoke(customer.getId(),sid,sid)));}
    @Test void concurrentRevocationHasOneEffect() throws Exception {var target=extra();var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->control.revoke(customer.getId(),sid,target.getSessionId()));var b=pool.submit(()->control.revoke(customer.getId(),sid,target.getSessionId()));assertEquals(a.get(10,TimeUnit.SECONDS),b.get(10,TimeUnit.SECONDS));assertTrue(tokens.findBySessionId(target.getSessionId()).orElseThrow().getRevoked());}finally{pool.shutdownNow();}}
    @Test void refreshRaceCannotRestoreRevokedSession() throws Exception {var login=auth.signin(new SigninRequest(customer.getEmail(),"security-test-password"));UUID current=UUID.fromString(jwt.verifyAccessToken(login.getAccessToken()).get("sid",String.class));var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var refresh=pool.submit(()->{start.await();try{return auth.refreshAccessToken(login.getRefreshToken());}catch(dustin.cex.domains.auth.exception.AuthException e){return null;}});var revoke=pool.submit(()->{start.await();try{return control.revoke(customer.getId(),current,current);}catch(ResponseStatusException e){return null;}});start.countDown();var rotated=refresh.get(15,TimeUnit.SECONDS);var removed=revoke.get(15,TimeUnit.SECONDS);assertTrue((rotated==null)!=(removed==null));assertTrue(tokens.findBySessionId(current).orElseThrow().getRevoked());}finally{pool.shutdownNow();}}
    @Test void httpOwnReadRevokeAndRoleBoundary() throws Exception {var target=extra();mvc.perform(get("/api/customer/security/sessions").header("Authorization","Bearer "+customerAccess)).andExpect(status().isOk()).andExpect(header().string("Cache-Control",org.hamcrest.Matchers.containsString("no-store")));mvc.perform(delete("/api/customer/security/sessions/"+target.getSessionId()).header("Authorization","Bearer "+customerAccess)).andExpect(status().isOk()).andExpect(jsonPath("$.requiresLogin").value(false));mvc.perform(get("/api/customer/security/sessions").header("Authorization","Bearer "+maker.access())).andExpect(status().isForbidden());mvc.perform(get("/api/customer/security/sessions")).andExpect(status().isUnauthorized());}
}
